begin;
create table public.measurement_units(id uuid primary key default gen_random_uuid(),shop_id uuid references shops(id) on delete cascade,name text not null,code text not null,family text not null check(family in('weight','volume','count','packaging')),dimension text,base_factor numeric,created_at timestamptz not null default now(),check(base_factor is null or base_factor>0));
create unique index measurement_unit_code on measurement_units(coalesce(shop_id,'00000000-0000-0000-0000-000000000000'),lower(code));
create unique index measurement_unit_name on measurement_units(coalesce(shop_id,'00000000-0000-0000-0000-000000000000'),lower(name));
insert into measurement_units(name,code,family,dimension,base_factor) values
('Milligram','mg','weight','weight',.001),('Gram','g','weight','weight',1),('Kilogram','kg','weight','weight',1000),('Ounce','oz','weight','weight',28.349523125),('Pound','lb','weight','weight',453.59237),
('Milliliter','ml','volume','volume',1),('Liter','L','volume','volume',1000),('Teaspoon (US)','tsp','volume','volume',4.92892159375),('Tablespoon (US)','tbsp','volume','volume',14.78676478125),('Cup (US)','cup','volume','volume',236.5882365);
insert into measurement_units(name,code,family) select name,code,case when code in('each','piece','dozen') then 'count' else 'packaging' end from (values('Each','each'),('Piece','piece'),('Pack','pack'),('Bag','bag'),('Bottle','bottle'),('Box','box'),('Case','case'),('Tray','tray'),('Jar','jar'),('Can','can'),('Carton','carton'),('Sack','sack'),('Bucket','bucket'),('Roll','roll'),('Sheet','sheet'),('Dozen','dozen'))x(name,code);
create table public.ingredient_unit_profiles(ingredient_id uuid primary key references ingredients(id) on delete cascade,shop_id uuid not null references shops(id) on delete cascade,purchase_unit text not null,purchase_size numeric not null default 1 check(purchase_size>0),purchase_content_unit text not null,purchase_factor numeric not null check(purchase_factor>0),purchase_label text not null default '',recipe_unit text not null,recipe_factor numeric not null check(recipe_factor>0),conversion_reason text not null default '',review_required boolean not null default false,updated_at timestamptz not null default now());
insert into ingredient_unit_profiles(ingredient_id,shop_id,purchase_unit,purchase_content_unit,purchase_factor,recipe_unit,recipe_factor,review_required) select id,shop_id,base_unit,base_unit,1,base_unit,1,not exists(select 1 from measurement_units u where u.shop_id is null and u.code=i.base_unit) from ingredients i;
create table public.ingredient_unit_audit(id uuid primary key default gen_random_uuid(),shop_id uuid not null references shops(id) on delete cascade,ingredient_id uuid references ingredients(id),action text not null,details jsonb not null,actor uuid,created_at timestamptz not null default now());
alter table measurement_units enable row level security;alter table ingredient_unit_profiles enable row level security;alter table ingredient_unit_audit enable row level security;
revoke all on measurement_units,ingredient_unit_profiles,ingredient_unit_audit from anon,authenticated;
create policy measurement_read on measurement_units for select to authenticated using((shop_id is null or shop_id=current_shop_id()) and ops_has_permission('operations_view'));
create policy ingredient_units_read on ingredient_unit_profiles for select to authenticated using(shop_id=current_shop_id() and ops_has_permission('operations_view'));
grant select on measurement_units,ingredient_unit_profiles to authenticated;
create function public.unit_definition(p_shop uuid,p_code text) returns measurement_units language sql stable security definer set search_path=public as $$select u from measurement_units u where code=p_code and (shop_id is null or shop_id=p_shop) order by shop_id nulls last limit 1$$;
create function public.unit_ratio(p_shop uuid,p_from text,p_to text) returns numeric language plpgsql stable security definer set search_path=public as $$declare a measurement_units;b measurement_units;begin if p_from=p_to then return 1;end if;a:=unit_definition(p_shop,p_from);b:=unit_definition(p_shop,p_to);if a.dimension is not null and a.dimension=b.dimension and a.base_factor is not null and b.base_factor is not null then return a.base_factor/b.base_factor;end if;raise exception 'A conversion between weight and volume requires an ingredient-specific conversion. Count and packaging units also require an explicit conversion.';end$$;
create function public.ingredient_unit_factor(p_id uuid,p_unit text) returns numeric language plpgsql stable security definer set search_path=public as $$declare i ingredients;p ingredient_unit_profiles;begin select * into i from ingredients where id=p_id and shop_id=current_shop_id();if not found or not ops_has_permission('operations_view') then raise exception 'Ingredient not found';end if;if p_unit=i.base_unit then return 1;end if;select * into p from ingredient_unit_profiles where ingredient_id=i.id and shop_id=i.shop_id;if p_unit=p.purchase_unit then return p.purchase_factor;end if;if p_unit=p.recipe_unit then return p.recipe_factor;end if;return unit_ratio(i.shop_id,p_unit,i.base_unit);end$$;
create function public.create_measurement_unit(p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare s uuid:=current_shop_id();r measurement_units;ref measurement_units;n text:=trim(p_values->>'name');c text:=trim(p_values->>'code');f text:=p_values->>'family';factor numeric;begin
 if current_shop_id() is null or not ops_has_permission('ingredient_manage') then raise exception 'Ingredient management access required';end if;
 if length(coalesce(n,'')) not between 1 and 60 or coalesce(c,'') !~ '^[A-Za-z][A-Za-z0-9_-]{0,19}$' or coalesce(f,'') not in('weight','volume','count','packaging') then raise exception 'Invalid unit name, abbreviation or type';end if;
 if exists(select 1 from measurement_units where (shop_id is null or shop_id=s) and(lower(code)=lower(c) or lower(name)=lower(n))) then raise exception 'Unit name or abbreviation already exists';end if;
 if nullif(p_values->>'reference','') is not null then ref:=unit_definition(s,p_values->>'reference');factor:=(p_values->>'quantity')::numeric;if ref.id is null or ref.dimension is null or factor is null or factor<=0 or factor>1000000000 then raise exception 'Choose a measurement unit and positive conversion';end if;if f in('weight','volume') and f<>ref.dimension then raise exception 'Custom measurement family must match its reference unit';end if;end if;
 insert into measurement_units(shop_id,name,code,family,dimension,base_factor) values(s,n,c,f,ref.dimension,factor*ref.base_factor) returning * into r;
 insert into ingredient_unit_audit(shop_id,action,details,actor) values(s,'unit_created',to_jsonb(r),auth.uid());return to_jsonb(r);end$$;
create function public.save_ingredient_unit_profile(p_id uuid,p_values jsonb) returns void language plpgsql security definer set search_path=public as $$declare i ingredients;pu text:=p_values->>'purchase_unit';content text:=p_values->>'purchase_content_unit';ru text:=p_values->>'recipe_unit';size numeric:=coalesce((p_values->>'purchase_size')::numeric,1);pf numeric;rf numeric;reason text:=trim(coalesce(p_values->>'conversion_reason',''));begin
 if current_shop_id() is null or not ops_has_permission('ingredient_manage') then raise exception 'Ingredient management access required';end if;select * into i from ingredients where id=p_id and shop_id=current_shop_id() for update;if not found then raise exception 'Ingredient not found';end if;
 pu:=coalesce(nullif(pu,''),i.base_unit);content:=coalesce(nullif(content,''),i.base_unit);ru:=coalesce(nullif(ru,''),i.base_unit);
 if (unit_definition(i.shop_id,pu)).id is null and pu<>i.base_unit or (unit_definition(i.shop_id,ru)).id is null and ru<>i.base_unit or size<=0 or size>1000000000 then raise exception 'Invalid purchase or recipe unit';end if;
 if nullif(p_values->>'purchase_base_factor','') is not null then if length(reason)<5 then raise exception 'An ingredient-specific conversion reason is required';end if;pf:=(p_values->>'purchase_base_factor')::numeric;else pf:=size*unit_ratio(i.shop_id,content,i.base_unit);end if;
 if nullif(p_values->>'recipe_base_factor','') is not null then if length(reason)<5 then raise exception 'An ingredient-specific conversion reason is required';end if;rf:=(p_values->>'recipe_base_factor')::numeric;else rf:=unit_ratio(i.shop_id,ru,i.base_unit);end if;
 if (unit_definition(i.shop_id,pu)).family in('weight','volume') and (unit_definition(i.shop_id,pu)).dimension=(unit_definition(i.shop_id,i.base_unit)).dimension and pf<>unit_ratio(i.shop_id,pu,i.base_unit) then raise exception 'Use a packaging unit for package-size conversions';end if;
 if (unit_definition(i.shop_id,ru)).family in('weight','volume') and (unit_definition(i.shop_id,ru)).dimension=(unit_definition(i.shop_id,i.base_unit)).dimension and rf<>unit_ratio(i.shop_id,ru,i.base_unit) then raise exception 'Scientific unit factors cannot be overridden';end if;
 if pf is null or rf is null or pf<=0 or rf<=0 or pf>1000000000000 or rf>1000000000000 then raise exception 'Invalid conversion factor';end if;
 if pu=ru and pf<>rf or pu=i.base_unit and pf<>1 or ru=i.base_unit and rf<>1 then raise exception 'The same unit cannot have conflicting conversion factors';end if;
 insert into ingredient_unit_profiles(ingredient_id,shop_id,purchase_unit,purchase_size,purchase_content_unit,purchase_factor,purchase_label,recipe_unit,recipe_factor,conversion_reason) values(i.id,i.shop_id,pu,size,content,pf,left(coalesce(p_values->>'purchase_label',''),120),ru,rf,reason) on conflict(ingredient_id) do update set purchase_unit=excluded.purchase_unit,purchase_size=excluded.purchase_size,purchase_content_unit=excluded.purchase_content_unit,purchase_factor=excluded.purchase_factor,purchase_label=excluded.purchase_label,recipe_unit=excluded.recipe_unit,recipe_factor=excluded.recipe_factor,conversion_reason=excluded.conversion_reason,review_required=(unit_definition(i.shop_id,i.base_unit)).id is null,updated_at=now();
 insert into ingredient_unit_audit(shop_id,ingredient_id,action,details,actor) values(i.shop_id,i.id,'unit_profile_saved',p_values||jsonb_build_object('purchase_factor',pf,'recipe_factor',rf),auth.uid());end$$;
-- Remove only the original closed-list constraints. Numeric balances and historical unit values remain untouched.
do $$declare c record;begin for c in select conrelid::regclass tbl,conname from pg_constraint where contype='c' and connamespace='public'::regnamespace and pg_get_constraintdef(oid) like '%base_unit%' and conrelid in('ingredients'::regclass,'ingredient_purchase_order_items'::regclass,'ingredient_purchase_receipt_items'::regclass) loop execute format('alter table %s drop constraint %I',c.tbl,c.conname);end loop;end$$;
create function public.ingredient_base_unit_guard() returns trigger language plpgsql security definer set search_path=public as $$begin
 if current_setting('workspace.lifecycle_mode',true) in('restore','purge') then return new;end if;
 if tg_op='UPDATE' and new.base_unit=old.base_unit then return new;end if;
 if (unit_definition(new.shop_id,new.base_unit)).id is null then raise exception 'Unknown workspace unit';end if;
 if tg_op='UPDATE' and(new.current_quantity<>0 or exists(select 1 from ingredient_inventory_movements where ingredient_id=new.id) or exists(select 1 from recipe_items where ingredient_id=new.id) or exists(select 1 from ingredient_purchase_order_items where ingredient_id=new.id)) then raise exception 'Base unit is locked by stock or history; create a new ingredient instead';end if;return new;end$$;
create trigger ingredient_base_unit before insert or update of base_unit on ingredients for each row execute function ingredient_base_unit_guard();
do $$declare d text;begin d:=pg_get_functiondef('upsert_ingredient(uuid,text,text,text,numeric,numeric,numeric,numeric,uuid,integer,boolean)'::regprocedure);d:=replace(d,$n$if p_base_unit not in ('g','ml','each') then raise exception 'Base unit must be g, ml, or each'; end if;$n$,$n$if (unit_definition(v_shop,p_base_unit)).id is null and not exists(select 1 from ingredients where id=p_ingredient_id and shop_id=v_shop and base_unit=p_base_unit) then raise exception 'Unknown workspace unit';end if;$n$);execute d;d:=pg_get_functiondef('create_purchase_item(text,text,text)'::regprocedure);d:=replace(d,$n$p_unit not in('g','ml','each')$n$,$n$(unit_definition(current_shop_id(),p_unit)).id is null$n$);execute d;end$$;
create function public.save_ingredient_with_units(p_values jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare id uuid;begin id:=upsert_ingredient(nullif(p_values->>'id','')::uuid,p_values->>'name',p_values->>'sku',p_values->>'base_unit',(p_values->>'opening_quantity')::numeric,(p_values->>'reorder_level')::numeric,(p_values->>'target_level')::numeric,(p_values->>'average_unit_cost')::numeric,nullif(p_values->>'preferred_supplier_id','')::uuid,(p_values->>'lead_time_days')::int,(p_values->>'active')::boolean);perform save_ingredient_unit_profile(id,p_values);return id;end$$;
alter table ingredient_purchase_order_items add column purchase_snapshot jsonb not null default '{}';
alter table ingredient_purchase_receipt_items add column purchase_snapshot jsonb not null default '{}';
alter table ingredient_purchase_needs add column purchase_snapshot jsonb not null default '{}';
alter table recipe_items add column entered_unit text,add column entered_quantity numeric;
-- Normalize before approval, verification, stock, cost and recipe code; preserve original entered data alongside the ledgers.
create function public.ingredient_purchase_factor(p_id uuid,p_item jsonb) returns numeric language plpgsql stable security definer set search_path=public as $$declare i ingredients;p ingredient_unit_profiles;n numeric;content text;u text:=p_item->>'purchase_unit';begin
 if not(p_item ? 'purchase_size') then return ingredient_unit_factor(p_id,u);end if;
 select * into i from ingredients where id=p_id and shop_id=current_shop_id();if not found or not ops_has_permission('operations_view') then raise exception 'Ingredient not found';end if;
 n:=(p_item->>'purchase_size')::numeric;content:=p_item->>'purchase_content_unit';if n is null or n<=0 or n>1000000000 or content is null then raise exception 'Invalid package size';end if;
 select * into p from ingredient_unit_profiles where ingredient_id=p_id and shop_id=i.shop_id;
 if u=p.purchase_unit and n=p.purchase_size and content=p.purchase_content_unit then return p.purchase_factor;end if;
 if coalesce((unit_definition(i.shop_id,u)).family,'') not in('packaging','count') then if n=1 and content=u then return ingredient_unit_factor(p_id,u);end if;raise exception 'Use a packaging unit for package-size conversions';end if;
 return n*unit_ratio(i.shop_id,content,i.base_unit);end$$;
revoke all on function ingredient_purchase_factor(uuid,jsonb) from public,anon,authenticated;
alter function create_ingredient_purchase_order(uuid,date,text,jsonb) rename to create_ingredient_purchase_order_before_units;
revoke all on function create_ingredient_purchase_order_before_units(uuid,date,text,jsonb) from public,anon,authenticated;
create function public.create_ingredient_purchase_order(p_supplier_id uuid,p_expected_date date,p_note text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare items jsonb:='[]';x jsonb;f numeric;v_order uuid;begin
 for x in select value from jsonb_array_elements(p_items) loop if x ? 'purchase_unit' then f:=ingredient_purchase_factor((x->>'ingredient_id')::uuid,x);items:=items||jsonb_build_array(x||jsonb_build_object('ordered_quantity',round((x->>'ordered_quantity')::numeric*f,3),'expected_unit_cost',round((x->>'expected_unit_cost')::numeric/f,6)));else items:=items||jsonb_build_array(x);end if;end loop;
 v_order:=create_ingredient_purchase_order_before_units(p_supplier_id,p_expected_date,p_note,items);
 for x in select value from jsonb_array_elements(p_items) loop if x ? 'purchase_unit' then f:=ingredient_purchase_factor((x->>'ingredient_id')::uuid,x);update ingredient_purchase_order_items set purchase_snapshot=jsonb_build_object('unit',x->>'purchase_unit','quantity',(x->>'ordered_quantity')::numeric,'unit_cost',(x->>'expected_unit_cost')::numeric,'factor',f,'label',coalesce(x->>'package_label',''),'package_size',x->'purchase_size','content_unit',x->>'purchase_content_unit','normalized_quantity',round((x->>'ordered_quantity')::numeric*f,3)) where order_id=v_order and ingredient_id=(x->>'ingredient_id')::uuid;end if;end loop;return v_order;end$$;
alter function verified_receive_ingredient_order(uuid,uuid,text,text,jsonb) rename to verified_receive_ingredient_order_before_units;
revoke all on function verified_receive_ingredient_order_before_units(uuid,uuid,text,text,jsonb) from public,anon,authenticated;
create function public.verified_receive_ingredient_order(p_order_id uuid,p_key uuid,p_invoice text,p_note text,p_items jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare items jsonb:='[]';x jsonb;li ingredient_purchase_order_items;f numeric;result jsonb;begin
 if not ops_has_permission('purchase_receive') then raise exception 'Receiving access required';end if;
 for x in select value from jsonb_array_elements(p_items) loop if x ? 'purchase_quantity' then select * into li from ingredient_purchase_order_items where id=(x->>'order_item_id')::uuid and order_id=p_order_id and shop_id=current_shop_id();if not found then raise exception 'Order item not found';end if;f:=coalesce((li.purchase_snapshot->>'factor')::numeric,1);items:=items||jsonb_build_array(x||jsonb_build_object('quantity_received',round((x->>'purchase_quantity')::numeric*f,3),'actual_unit_cost',round((x->>'actual_unit_cost')::numeric/f,6)));else items:=items||jsonb_build_array(x);end if;end loop;
 result:=verified_receive_ingredient_order_before_units(p_order_id,p_key,p_invoice,p_note,items);
 for x in select value from jsonb_array_elements(p_items) loop if x ? 'purchase_quantity' then select * into li from ingredient_purchase_order_items where id=(x->>'order_item_id')::uuid and order_id=p_order_id and shop_id=current_shop_id();f:=coalesce((li.purchase_snapshot->>'factor')::numeric,1);update ingredient_purchase_receipt_items set purchase_snapshot=li.purchase_snapshot||jsonb_build_object('received_quantity',(x->>'purchase_quantity')::numeric,'actual_purchase_unit_cost',(x->>'actual_unit_cost')::numeric,'normalized_received_quantity',round((x->>'purchase_quantity')::numeric*f,3)) where receipt_id=(result->>'receipt_id')::uuid and order_item_id=li.id and shop_id=current_shop_id();end if;end loop;return result;end$$;
alter function upsert_product_recipe(uuid,uuid,numeric,numeric,numeric,numeric,numeric,numeric,boolean,boolean,jsonb) rename to upsert_product_recipe_before_units;
revoke all on function upsert_product_recipe_before_units(uuid,uuid,numeric,numeric,numeric,numeric,numeric,numeric,boolean,boolean,jsonb) from public,anon,authenticated;
create function public.upsert_product_recipe(p_recipe_id uuid,p_product_id uuid,p_batch_yield numeric,p_labor_cost numeric,p_overhead_cost numeric,p_packaging_cost_per_unit numeric,p_expected_waste_percent numeric,p_target_margin_percent numeric,p_pricing_enabled boolean,p_active boolean,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare items jsonb:='[]';x jsonb;v_recipe uuid;begin
 for x in select value from jsonb_array_elements(p_items) loop if nullif(x->>'unit','') is not null then items:=items||jsonb_build_array(x||jsonb_build_object('quantity_required',round((x->>'quantity_required')::numeric*ingredient_unit_factor((x->>'ingredient_id')::uuid,x->>'unit'),3)));else items:=items||jsonb_build_array(x);end if;end loop;
 v_recipe:=upsert_product_recipe_before_units(p_recipe_id,p_product_id,p_batch_yield,p_labor_cost,p_overhead_cost,p_packaging_cost_per_unit,p_expected_waste_percent,p_target_margin_percent,p_pricing_enabled,p_active,items);
 for x in select value from jsonb_array_elements(p_items) loop update recipe_items set entered_unit=x->>'unit',entered_quantity=(x->>'quantity_required')::numeric where recipe_id=v_recipe and ingredient_id=(x->>'ingredient_id')::uuid;end loop;
 update recipe_versions set snapshot=snapshot||jsonb_build_object('entered_items',p_items) where recipe_id=v_recipe and version=(select version from product_recipes where product_recipes.id=v_recipe limit 1);return v_recipe;end$$;

alter function get_recipe_inventory_overview() rename to get_recipe_inventory_before_units;
revoke all on function get_recipe_inventory_before_units() from public,anon,authenticated;
create function public.get_recipe_inventory_overview() returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;begin result:=get_recipe_inventory_before_units();return jsonb_set(result,'{ingredients}',coalesce((select jsonb_agg(x||jsonb_build_object('unit_profile',(select to_jsonb(p) from ingredient_unit_profiles p where p.ingredient_id=(x->>'id')::uuid and p.shop_id=current_shop_id()))) from jsonb_array_elements(result->'ingredients')x),'[]'));end$$;
alter function get_ingredient_purchasing(text,integer) rename to get_ingredient_purchasing_before_units;
revoke all on function get_ingredient_purchasing_before_units(text,integer) from public,anon,authenticated;
create function public.get_ingredient_purchasing(p_search text default '',p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$declare result jsonb;begin result:=get_ingredient_purchasing_before_units(p_search,p_offset);
 if not ops_has_permission('costs_view') then result:=jsonb_set(result,'{needs}',coalesce((select jsonb_agg(n||jsonb_build_object('purchase_snapshot',coalesce(n->'purchase_snapshot','{}')-'unit_cost')) from jsonb_array_elements(result->'needs')n),'[]'));end if;
 result:=jsonb_set(result,'{ingredients}',coalesce((select jsonb_agg(x||jsonb_build_object('unit_profile',(select to_jsonb(p) from ingredient_unit_profiles p where p.ingredient_id=(x->>'id')::uuid and p.shop_id=current_shop_id()))) from jsonb_array_elements(result->'ingredients')x),'[]'));
 result:=jsonb_set(result,'{orders}',coalesce((select jsonb_agg(o||jsonb_build_object('items',coalesce((select jsonb_agg(li||jsonb_build_object('purchase_snapshot',(select case when ops_has_permission('costs_view') then p.purchase_snapshot else p.purchase_snapshot-'unit_cost' end from ingredient_purchase_order_items p where p.id=(li->>'id')::uuid and p.shop_id=current_shop_id()))) from jsonb_array_elements(o->'items')li),'[]'))) from jsonb_array_elements(result->'orders')o),'[]'));return result;end$$;
create function public.create_unit_purchase_need(p_values jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare x jsonb:=p_values->'p_items'->0;factor numeric;v_id uuid;begin
 if jsonb_array_length(p_values->'p_items')<>1 then raise exception 'One purchase item per need';end if;
 factor:=ingredient_purchase_factor((x->>'ingredient_id')::uuid,x);
 v_id:=create_ingredient_purchase_need((x->>'ingredient_id')::uuid,round((x->>'ordered_quantity')::numeric*factor,3),(p_values->>'p_supplier_id')::uuid,round((x->>'expected_unit_cost')::numeric/factor,6),p_values->>'p_note');
 update ingredient_purchase_needs set purchase_snapshot=jsonb_build_object('unit',x->>'purchase_unit','quantity',(x->>'ordered_quantity')::numeric,'unit_cost',(x->>'expected_unit_cost')::numeric,'factor',factor,'label',coalesce(x->>'package_label',''),'package_size',x->'purchase_size','content_unit',x->>'purchase_content_unit','normalized_quantity',round((x->>'ordered_quantity')::numeric*factor,3)) where id=v_id and shop_id=current_shop_id();return v_id;end$$;
alter function order_ingredient_purchase_need(uuid) rename to order_ingredient_purchase_need_before_units;
revoke all on function order_ingredient_purchase_need_before_units(uuid) from public,anon,authenticated;
create function public.order_ingredient_purchase_need(p_id uuid) returns uuid language plpgsql security definer set search_path=public as $$declare v_order uuid;n ingredient_purchase_needs;begin v_order:=order_ingredient_purchase_need_before_units(p_id);select * into n from ingredient_purchase_needs where id=p_id and shop_id=current_shop_id();update ingredient_purchase_order_items set purchase_snapshot=n.purchase_snapshot where order_id=v_order and ingredient_id=n.ingredient_id and shop_id=current_shop_id();return v_order;end$$;
revoke all on function get_recipe_inventory_overview(),get_ingredient_purchasing(text,integer),create_unit_purchase_need(jsonb),order_ingredient_purchase_need(uuid) from public,anon,authenticated;
grant execute on function get_recipe_inventory_overview(),get_ingredient_purchasing(text,integer),create_unit_purchase_need(jsonb),order_ingredient_purchase_need(uuid) to authenticated;

-- Register only tenant-owned configuration for existing secret-free, remapping restore machinery.
insert into workspace_backup_tables(table_name,columns) select t,array_agg(c.column_name::text order by c.ordinal_position) from unnest(array['measurement_units','ingredient_unit_profiles','ingredient_unit_audit'])t join information_schema.columns c on c.table_schema='public' and c.table_name=t group by t;
update workspace_backup_tables set columns=columns||array['purchase_snapshot'] where table_name in('ingredient_purchase_order_items','ingredient_purchase_receipt_items','ingredient_purchase_needs');
update workspace_backup_tables set columns=columns||array['entered_unit','entered_quantity'] where table_name='recipe_items';
